/*    BUBBLE START     */
/** floating animation start **/
@keyframes bubble-flow-1 {
  0% {
    transform: translate(7vw, -86vh);
  }
  25% {
    transform: translate(28vw, -63vh);
  }
  50% {
    transform: translate(74vw, -13vh);
  }
  75% {
    transform: translate(23vw, -94vh);
  }
  100% {
    transform: translate(66vw, -28vh);
  }
}
@keyframes bubble-flow-2 {
  0% {
    transform: translate(100vw, -4vh);
  }
  25% {
    transform: translate(1vw, -91vh);
  }
  50% {
    transform: translate(82vw, -77vh);
  }
  75% {
    transform: translate(98vw, -83vh);
  }
  100% {
    transform: translate(96vw, -54vh);
  }
}
@keyframes bubble-flow-3 {
  0% {
    transform: translate(44vw, -32vh);
  }
  25% {
    transform: translate(90vw, -12vh);
  }
  50% {
    transform: translate(4vw, -45vh);
  }
  75% {
    transform: translate(26vw, -25vh);
  }
  100% {
    transform: translate(36vw, -52vh);
  }
}
@keyframes bubble-flow-4 {
  0% {
    transform: translate(57vw, -95vh);
  }
  25% {
    transform: translate(99vw, -31vh);
  }
  50% {
    transform: translate(33vw, -91vh);
  }
  75% {
    transform: translate(32vw, -25vh);
  }
  100% {
    transform: translate(43vw, -70vh);
  }
}
@keyframes bubble-flow-5 {
  0% {
    transform: translate(96vw, -24vh);
  }
  25% {
    transform: translate(77vw, -40vh);
  }
  50% {
    transform: translate(49vw, -27vh);
  }
  75% {
    transform: translate(4vw, -78vh);
  }
  100% {
    transform: translate(24vw, -88vh);
  }
}
/** floating animation end **/
/** inflation animation start **/
@keyframes bubble-inflate {
  from {
    transform: scale(1);
    opacity: 100;
    top: 50%;
    left: 50%;
  }
  to {
    transform: scale(5);
    background: white;
    border: none;
    opacity: 0;
    top: 50%;
    left: 50%;
  }
}
/** inflation animation end **/
/*    BUBBLE END     */
