/* DROPDOWN START   */
@keyframes grow-down {
  from {
    transform: scaleY(0);
  }
  to {
    transform: scaleY(1);
  }
}
@keyframes shrink-up {
  from {
    transform: scaleY(1);
    display: block;
  }
  to {
    transform: scaleY(0);
    display: none;
  }
}
/* DROPDOWN END   */
@keyframes grow {
  from {
    height: 0vh;
  }
  to {
    height: 50vh;
  }
}
@keyframes unblur {
  0% {
    filter: blur(15px);
  }
  35% {
    filter: blur(0px);
  }
  65% {
    filter: blur(0px);
  }
  100% {
    filter: blur(15px);
  }
}
@keyframes unfade {
  0% {
    opacity: 0;
  }
  50% {
    opacity: 1;
  }
  100% {
    opacity: 0;
  }
}
@keyframes unfade2 {
  0% {
    opacity: 0;
  }
  100% {
    opacity: 1;
  }
}
