@media (orientation: landscape) {
  #pop-up {
    background: white;
    height: 100vh;
    width: 100vh;
    padding: 10px;
  }
  #pop-up .img-container-wrapper {
    height: 33.3333333333vh;
    width: 100%;
    position: relative;
  }
  #pop-up .img-container-wrapper #click-here {
    position: absolute;
    top: 35%;
    left: 15%;
    height: 50px;
    width: 50px;
    transform: rotate(15deg);
    z-index: 5;
  }
  #pop-up .img-container-wrapper .img-container {
    width: 33.3333333333vh;
    height: 33.3333333333vh;
    overflow: hidden;
    border-radius: 1000px;
    animation: color-pulse-blue 5s linear infinite;
  }
  #pop-up .img-container-wrapper .img-container #page-icon {
    object-fit: cover;
    width: 100%;
  }
  #pop-up .img-container-wrapper .img-container:active {
    border: 3px solid black !important;
  }
  #pop-up .exit-btn-container {
    /* position: absolute; */
    width: 100%;
    overflow: hidden;
  }
  #pop-up .exit-btn-container .exit-btn {
    margin: 0px 7px;
  }
  #pop-up p {
    overflow: hidden scroll;
    height: calc(33.3333333333vh + 10px);
  }
}
@media screen and (min-width: 768px) {
  nav .nav-btn.dropdown {
    position: relative;
  }
  nav .nav-btn.dropdown .dropdown-list {
    width: 200px !important;
    top: 40px;
    left: -50px;
  }
  nav .nav-btn a {
    height: 30px !important;
    width: 100%;
  }
  main.about > .container {
    max-width: 650px;
  }
}
body {
  /* background: #4b4b4b; */
  background: black;
  font-size: 12px;
  font-family: "Montserrat", sans-serif;
  text-wrap: wrap;
  text-align: center;
  margin: 0px !important;
}

nav {
  height: 50px;
}

a {
  text-decoration: none;
  color: inherit;
}
a:active {
  background: inherit;
  -webkit-tap-highlight-color: transparent !important;
}
a:visted {
  background: inherit;
}

header > nav {
  height: 100%;
}

main section:nth-child(1) {
  height: 125px;
  color: #aea9a9;
}

main section:nth-child(2) {
  height: calc(100% - 125px);
}

main > section {
  width: 100%;
}

h1 {
  text-align: center;
  font-size: 25px !important;
}

h2 {
  text-align: center;
  font-size: 15px !important;
  font-weight: 500;
}

main.home {
  overflow: hidden !important;
  height: calc(100vh - 50px);
}

main.about {
  color: white;
}
main.about div.description {
  /* border-bottom: 1px solid $text-grey; */
  padding: 15px 10px 150px 10px;
  animation: unblur 1s both linear;
  animation-timeline: view();
  min-height: 100vh;
  position: relative;
  background-size: 100% auto !important;
  mask-image: linear-gradient(from top, black 30%, transparent 100%), linear-gradient(to bottom, black 60%, transparent 100%);
  -webkit-mask-image: linear-gradient(to bottom, black 45%, transparent 100%);
}
main.about article {
  backdrop-filter: blur(5px);
  padding: 5px;
  border-radius: 10px;
}
main.about img.background {
  height: 100%;
  object-fit: cover;
  position: absolute;
  top: 0px;
  left: 0px;
}
main.about h3 {
  margin-top: 25px;
}
main.about ul li {
  animation-timeline: view(block 0% 10%);
  transform: translateY(150vh);
  margin: 5px 0px;
}
main.about ul.improvements li {
  text-align: left;
}
main.about ul.skills li img {
  height: 15px;
  width: 15px;
}

.last-block {
  height: 150px;
}

main.about-me {
  overflow-x: hidden;
}
main.about-me section.intro h1.animate {
  position: absolute;
  color: #343434;
  top: 175px;
  z-index: 2;
  opacity: 0;
  animation: 2s unfade2 forwards ease-out;
}
main.about-me section.intro #me.animate {
  animation: 3s grow-70-100 forwards ease-out;
}
main.about-me section.intro h3.animate {
  animation: 2s rise-0-30 forwards ease-out;
}
main.about-me section.intro p.animate {
  animation: 2s 0.5s rise-0-30 forwards ease-out;
}
main.about-me section.intro #me {
  height: 70vh;
  object-fit: cover;
  mask-image: linear-gradient(to bottom, black 45%, transparent 100%);
  -webkit-mask-image: linear-gradient(to bottom, black 70%, transparent 100%);
}
main.about-me section {
  height: auto;
  color: white;
}
main.about-me ul {
  text-align: center !important;
  width: 100%;
  padding: 0px;
  font-weight: 100;
}
main.about-me ul > li {
  width: 100%;
  list-style-position: inside;
}
main.about-me .max-card-size {
  min-height: 175px;
  min-width: 175px;
}
main.about-me .skill-card {
  min-height: 175px;
  min-width: 175px;
  position: relative;
  overflow: hidden !important;
}
main.about-me .skill-card h5 {
  position: absolute;
  font-size: 15px;
  top: -27px;
  /* background: #00000030; */
  width: 100%;
  height: 25px;
}
main.about-me .skill-card ul {
  width: 100%;
  height: calc(100% - 25px);
  padding-top: 25px;
  overflow: hidden scroll;
}
main.about-me .trapezium-container {
  height: auto;
  width: auto;
  position: relative !important;
  margin: 15px 0px;
}
main.about-me .trapezium-container.animate:nth-child(2n) {
  animation: 0.75s right-n100-0 forwards linear;
}
main.about-me .trapezium-container.animate:nth-child(2n+1) {
  animation: 0.75s left-200-0 forwards linear;
}
main.about-me .trapezium-container polygon {
  z-index: 1;
  position: absolute;
  top: 0px;
  left: 0px;
}
main.about-me .trapezium-container:nth-child(2n+1) {
  /* transform: translateX(100vw); */
}
main.about-me .trapezium-container:nth-child(2n+1) p {
  position: absolute;
  top: 0px;
  right: 0px;
  text-align: right !important;
}
main.about-me .trapezium-container:nth-child(2n) {
  /* transform: translateX(-100vw); */
}
main.about-me .trapezium-container:nth-child(2n) p {
  position: absolute;
  top: 0px;
  left: 0px;
  text-align: left !important;
}
main.about-me .trapezium-container p {
  padding: 0px 5px;
  z-index: 2;
  width: 75%;
}